168	/// Convenience helper to build `TrajectoryGraph` and calculate monotonicity score.
169	pub fn calculate_monotonicity(transcript: &CanonicalTranscript) -> f32 {
170	    let mut tg = TrajectoryGraph::new();
171	    for turn in &transcript.turns {
172	        for call in &turn.tool_calls {
173	            let is_mutation = matches!(call.intent, ToolIntent::FileEdit { .. } | ToolIntent::FileCreate { .. });
174	            tg.push_tool(ToolNode {
175	                turn_index: turn.turn_index,
176	                tool_name: call.tool_name.clone(),
177	                target_symbol: None,
178	                target_file: None,
179	                is_mutation,
180	                had_error: false,
181	            });
182	        }
183	    }
184	    tg.calculate_monotonicity()
185	}
