22	/// Scans `text` for `github.com/{owner}/{repo}/pull/{digits}` substrings via manual
23	/// string splitting (no regex crate is available in this workspace).
24	fn find_pr_matches(text: &str) -> Vec<(CompactString, CompactString, CompactString)> {
25	    let mut matches = Vec::new();
26	    let marker = "github.com/";
27	    let mut search_from = 0;
28	
29	    while let Some(rel_idx) = text[search_from..].find(marker) {
30	        let start = search_from + rel_idx + marker.len();
31	        let remainder = &text[start..];
32	        let mut segments = remainder.splitn(4, '/');
33	
34	        let owner = segments.next().unwrap_or("");
35	        let repo = segments.next().unwrap_or("");
36	        let literal_pull = segments.next().unwrap_or("");
37	        let tail = segments.next().unwrap_or("");
38	
39	        if !owner.is_empty() && !repo.is_empty() && literal_pull == "pull" {
40	            let digits: String = tail.chars().take_while(|c| c.is_ascii_digit()).collect();
41	            if !digits.is_empty() {
42	                matches.push((CompactString::new(owner), CompactString::new(repo), CompactString::new(digits)));
43	            }
44	        }
45	
46	        search_from = start;
47	    }
48	
49	    matches
50	}
